def start_histories(apps, schema_editor):
    """Each existing item gets its "added to the plan" entry, dated when it was added."""
    RemediationItem = apps.get_model("remediation", "RemediationItem")
    RemediationActivity = apps.get_model("remediation", "RemediationActivity")
    for item in RemediationItem.objects.select_related("owner").iterator():
        entry = RemediationActivity.objects.create(
            item=item, actor=item.owner, actor_username=item.owner.username, kind="created"
        )
        RemediationActivity.objects.filter(pk=entry.pk).update(created_at=item.created_at)


